import { asset, R, F, L, O, P, slab, bolts, ribs, chair, plant, books, C, group, poly, ellipse, circle, n } from "./genre-tusche.mjs";

const each = (count, draw) => Array.from({ length: count }, (_, i) => draw(i)).join("");
const grain = (x, y, w, h, color = "#725238") => each(3, i => P(`M${x + 4} ${y + (i + 1) * h / 4}q${w / 3} -2 ${w - 8} 0`, "none", color, .6));
const ring = (x, y, r, color, width = 2) => circle(x, y, r, { fill: "none", stroke: color, "stroke-width": width });
const spokes = (x, y, r, count, color, width = 2) => each(count, i => L(x, y, x + Math.cos(i * Math.PI * 2 / count) * r, y + Math.sin(i * Math.PI * 2 / count) * r, color, width));
const gear = (x, y, r, color = "#c8a366", count = 12) => each(count, i => group({ transform: `rotate(${i * 360 / count} ${x} ${y})` }, R(x - 2.5, y - r - 3, 5, 8, color, .8))) + O(x, y, r, color) + ring(x, y, r * .65, "#735335", 1) + O(x, y, r * .28, C.dark);
const gauge = (x, y, r = 7, angle = -30) => O(x, y, r, "#eee0b6") + each(5, i => group({ transform: `rotate(${i * 45 - 90} ${x} ${y})` }, L(x, y - r + 1.5, x, y - r + 3, "#5f5145", .6))) + group({ transform: `rotate(${angle} ${x} ${y})` }, L(x, y + 1, x, y - r + 2, "#a7473e", 1.2)) + O(x, y, 1.2, C.dark);
const rope = (x, y, radius, turns = 4) => each(turns, i => ring(x, y, radius - i * 2.3, i % 2 ? "#ddc79a" : "#8e7851", 1.7));

